package com.hms.appointments;
import com.hms.queue.*; import com.hms.tenancy.*; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/public/hospitals/{tenantSlug}/appointments") public class PublicAppointmentStatusController {private final TenantRepository tenants;private final AppointmentRepository appointments;private final PatientRepository patients;private final QueueTokenRepository tokens;public PublicAppointmentStatusController(TenantRepository t,AppointmentRepository a,PatientRepository p,QueueTokenRepository q){tenants=t;appointments=a;patients=p;tokens=q;} @GetMapping("/status") public PublicAppointmentStatusDto status(@PathVariable String tenantSlug,@RequestParam UUID appointmentId,@RequestParam String phone){UUID tenant=tenants.findBySlug(tenantSlug).filter(t->t.getStatus()!=TenantStatus.SUSPENDED&&t.getStatus()!=TenantStatus.CANCELLED&&t.getStatus()!=TenantStatus.EXPIRED).map(Tenant::getId).orElseThrow(()->new IllegalArgumentException("Hospital is not accepting public lookup"));Appointment appointment=appointments.findById(appointmentId).filter(a->a.getTenantId().equals(tenant)).orElseThrow(()->new IllegalArgumentException("Appointment not found"));patients.findById(appointment.getPatientId()).filter(p->p.getTenantId().equals(tenant)&&p.getPhone().equals(phone.trim())).orElseThrow(()->new IllegalArgumentException("Appointment not found"));QueueToken token=tokens.findByAppointmentId(appointmentId).orElse(null);return new PublicAppointmentStatusDto(appointment.getId(),appointment.getStartsAt(),appointment.getStatus(),token==null?null:token.getStatus(),token==null?null:token.getTokenNumber(),token!=null&&token.isPriority());}}
